-- Athena saved query (Product_B2C_Intl)
-- ID: 7b3d4b67-69d9-4ced-9d40-27bc39b2f156
-- Name: Free Seat Pvt seats - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH RTC_SDs AS ( SELECT operator_id rtc_id, CASE WHEN operator_id = 15443 THEN 'WBSTC' WHEN operator_id = 16426 THEN 'WBTC (CTC)' WHEN operator_id = 32272 THEN 'SBSTC' WHEN operator_id = 24978 THEN 'NBSTC' ELSE 'NA' END AS rtc_name, source_location_id, destination_location_id FROM "transaction"."bus_ticket_events" WHERE 1 = 1 AND time_of_event >= TIMESTAMP '2026-05-24 18:30:00' AND time_of_event < TIMESTAMP '2026-06-07 18:30:00' AND country_code = 'IND' AND operator_id IN (15443, 16426, 32272, 24978) AND sales_channel IN ('RB:MOBILEWEB#iosapp', 'RB:MOBILEWEB#droidapp', 'WEBDIRECT', 'MOBILEWEB') AND status = 'CONFIRMED' AND event_class = 2 AND event_type = 101 GROUP BY 1, 2, 3, 4 ) SELECT -- CAST(DATE_TRUNC('day', at_timezone(p.time_of_event, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN p.time_of_event >= TIMESTAMP '2026-05-24 18:30:00' AND p.time_of_event <= TIMESTAMP '2026-05-31 18:30:00' THEN 'Before Free Seats' WHEN p.time_of_event >= TIMESTAMP '2026-05-31 18:30:00' AND p.time_of_event <= TIMESTAMP '2026-06-07 18:30:00' THEN 'After Free Seats' END AS time_period, r.rtc_id, r.rtc_name, CASE WHEN operator_id IN (15443, 16426, 32272, 24978) THEN 'RTC' ELSE 'Pvt' END AS Rtc_Pvt, -- p.source_location_id, p.destination_location_id,, COUNT(DISTINCT p.tin) txn_count, (SUM(no_of_males) + SUM(no_of_females)) pvt_seats, SUM(no_of_males) pvt_male_seats, SUM(no_of_females) pvt_female_seats FROM "transaction"."bus_ticket_events" p INNER JOIN RTC_SDs r ON r.source_location_id = p.source_location_id AND r.destination_location_id = p.destination_location_id WHERE 1 = 1 AND time_of_event >= TIMESTAMP '2026-05-24 18:30:00' AND time_of_event < TIMESTAMP '2026-06-07 18:30:00' AND country_code = 'IND' AND sales_channel IN ('RB:MOBILEWEB#iosapp', 'RB:MOBILEWEB#droidapp', 'WEBDIRECT', 'MOBILEWEB') AND status = 'CONFIRMED' AND event_class = 2 AND event_type = 101 GROUP BY 1, 2, 3, 4
